-- report: cohort_retention_long
WITH customer_months AS (SELECT customer_id, date(strftime('%Y-%m-01', order_date)) AS purchase_month FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id, purchase_month), cohorts AS (SELECT customer_id, MIN(purchase_month) AS cohort_month FROM customer_months GROUP BY customer_id), cohort_activity AS (SELECT c.cohort_month, cm.purchase_month, ((CAST(strftime('%Y', cm.purchase_month) AS INTEGER) - CAST(strftime('%Y', c.cohort_month) AS INTEGER)) * 12 + CAST(strftime('%m', cm.purchase_month) AS INTEGER) - CAST(strftime('%m', c.cohort_month) AS INTEGER)) AS month_number, cm.customer_id FROM customer_months cm JOIN cohorts c ON c.customer_id = cm.customer_id), cohort_size AS (SELECT cohort_month, COUNT(DISTINCT customer_id) AS cohort_customers FROM cohort_activity WHERE month_number = 0 GROUP BY cohort_month) SELECT ca.cohort_month, ca.month_number, COUNT(DISTINCT ca.customer_id) AS active_customers, cs.cohort_customers, ROUND(100.0 * COUNT(DISTINCT ca.customer_id) / cs.cohort_customers, 2) AS retention_percent FROM cohort_activity ca JOIN cohort_size cs ON cs.cohort_month = ca.cohort_month WHERE ca.month_number BETWEEN 0 AND 3 GROUP BY ca.cohort_month, ca.month_number, cs.cohort_customers ORDER BY ca.cohort_month, ca.month_number;

-- report: cohort_matrix
WITH customer_months AS (SELECT customer_id, date(strftime('%Y-%m-01', order_date)) AS purchase_month FROM orders WHERE customer_id IS NOT NULL GROUP BY customer_id, purchase_month), cohorts AS (SELECT customer_id, MIN(purchase_month) AS cohort_month FROM customer_months GROUP BY customer_id), cohort_activity AS (SELECT c.cohort_month, ((CAST(strftime('%Y', cm.purchase_month) AS INTEGER) - CAST(strftime('%Y', c.cohort_month) AS INTEGER)) * 12 + CAST(strftime('%m', cm.purchase_month) AS INTEGER) - CAST(strftime('%m', c.cohort_month) AS INTEGER)) AS month_number, cm.customer_id FROM customer_months cm JOIN cohorts c ON c.customer_id = cm.customer_id), cohort_size AS (SELECT cohort_month, COUNT(DISTINCT customer_id) AS cohort_customers FROM cohort_activity WHERE month_number = 0 GROUP BY cohort_month), retention AS (SELECT cohort_month, month_number, 100.0 * COUNT(DISTINCT customer_id) / (SELECT cohort_customers FROM cohort_size cs WHERE cs.cohort_month = ca.cohort_month) AS retention_percent FROM cohort_activity ca WHERE month_number BETWEEN 0 AND 3 GROUP BY cohort_month, month_number) SELECT cohort_month, ROUND(MAX(CASE WHEN month_number = 0 THEN retention_percent END), 2) AS month_0_percent, ROUND(MAX(CASE WHEN month_number = 1 THEN retention_percent END), 2) AS month_1_percent, ROUND(MAX(CASE WHEN month_number = 2 THEN retention_percent END), 2) AS month_2_percent, ROUND(MAX(CASE WHEN month_number = 3 THEN retention_percent END), 2) AS month_3_percent FROM retention GROUP BY cohort_month ORDER BY cohort_month;
